method strlen(string: string) returns (length: int)
    requires string != null
    ensures length >= 0
    ensures length == |string|
{
    var len := 0;
    // Loop through each character in the string to count the length
    var i := 0;
    while i < |string|
        // The loop invariant ensures that len is the number of characters counted so far
        invariant 0 <= len <= i
        invariant i <= |string|
    {
        len := len + 1;
        i := i + 1;
    }
    length := len;
}

